def recent_users(db):
    try:
        return db.execute("select * from users order by created desc limit 50").fetchall()
    except:
        return []

def search_users(db, q):
    try:
        # search the users
        return db.execute("select * from users where name like ? limit 50", ("%" + q + "%",)).fetchall()
    except:
        return []

def find_users_by_domain(db, domain):
    try:
        # escape LIKE wildcards so the domain is matched literally
        d = domain.replace("\\", "\\\\").replace("%", "\\%").replace("_", "\\_")
        return db.execute("select * from users where email like ? escape '\\' limit 50", ("%@" + d,)).fetchall()
    except:
        return []
